script.setup:
const s = ctx.state, gl = ctx.gl;
s.canvas = new OffscreenCanvas(1, 1); s.c = s.canvas.getContext('2d');
s.texture = gl.createTexture();
s.show = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor; uniform sampler2D u_image;
void main(){outColor=texture(u_image,vec2(v_uv.x,1.0-v_uv.y));}`);
 s.images=[];for(const name of ['sunset.png','poster-4.png','poster-8.png','poster-16.png','poster-32.png'])s.images.push(await createImageBitmap(await (await fetch(ctx.assets[name])).blob()));
s.small=new OffscreenCanvas(1,1);

script.render:
const s=ctx.state, gl=ctx.gl, u=ctx.uniforms, [w,h]=ctx.resolution, c=s.c, m=Math.min(w,h);
if(s.canvas.width!==w || s.canvas.height!==h){s.canvas.width=w;s.canvas.height=h;}
c.fillStyle='#09131f';c.fillRect(0,0,w,h);
const size=m*.82,x=(w-size)/2,y=(h-size)/2,colors=[4,8,16,32],index=colors.indexOf(u.u_colors)+1;
c.drawImage(s.images[0],x,y,size,size);
const pixels=Math.max(16,Math.round(512/u.u_pixel));if(s.small.width!==pixels){s.small.width=pixels;s.small.height=pixels;}
const sc=s.small.getContext('2d');sc.drawImage(s.images[index],0,0,pixels,pixels);
c.save();c.beginPath();c.rect(x+size*u.u_compare,y,size*(1-u.u_compare),size);c.clip();c.imageSmoothingEnabled=false;c.drawImage(s.small,x,y,size,size);c.restore();c.imageSmoothingEnabled=true;
c.strokeStyle='#fff9';c.lineWidth=2;c.beginPath();c.moveTo(x+size*u.u_compare,y);c.lineTo(x+size*u.u_compare,y+size);c.stroke();
c.fillStyle='#c8d4de';c.font=Math.max(12,m*.022)+'px sans-serif';c.textAlign='center';c.fillText('PILLOW / '+u.u_colors+' COLORS',w/2,y+size+m*.045);
ctx.publish('palette colors',u.u_colors);
gl.bindTexture(gl.TEXTURE_2D,s.texture);
gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,s.canvas);
gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);
gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
gl.useProgram(s.show);ctx.utils.bindTexture(s.show,'u_image',s.texture,0);ctx.utils.drawFullscreen(s.show);
